        float c_re0 = x0 + i * dx;
        float c_re1 = x0 + (i + 1) * dx;
        float c_re2 = x0 + (i + 2) * dx;
        float c_re3 = x0 + (i + 3) * dx;
        float c_re4 = x0 + (i + 4) * dx;
        float c_re5 = x0 + (i + 5) * dx;
        float c_re6 = x0 + (i + 6) * dx;
